INSERT INTO salons (id, owner_id, area_id, name, slug, address, phone, description, rating, is_active, created_at, updated_at) VALUES (1, 3, 1, 'The Crown & Razor Barbershop', 'the-crown-and-razor', '24 26th of July St, Zamalek, Cairo', '+20 2 2736 1234', 'Premier luxury gentlemen’s grooming parlour. Signature hot towel shaves, precision fade haircuts, and handcrafted beard treatments in an opulent vintage atmosphere.', 4.9, 1, '2026-08-20 02:36:01', '2026-08-20 02:36:01');
INSERT INTO salons (id, owner_id, area_id, name, slug, address, phone, description, rating, is_active, created_at, updated_at) VALUES (2, 6, 2, 'Lumière Hair Atelier', 'lumiere-hair-atelier', '14 Road 9, Maadi, Cairo', '+20 100 555 9901', 'Modern high-fashion hair salon offering luxury balayage, organic hair coloring, treatments, and custom hair styling by certified European master colorists.', 4.8, 1, '2026-08-20 02:36:03', '2026-08-20 02:36:03');
INSERT INTO salons (id, owner_id, area_id, name, slug, address, phone, description, rating, is_active, created_at, updated_at) VALUES (3, 7, 11, 'Vintage Gentleman Barbers', 'vintage-gentleman-barbers', ' Victor Emanuel Square, Smouha, Alexandria', '+20 100 555 9902', 'Traditional barbershop committed to timeless cuts, beard sculpting, relaxed scalp massages, and espresso bar lounge for gentlemen.', 4.7, 1, '2026-08-20 02:36:04', '2026-08-20 02:36:04');
INSERT INTO salons (id, owner_id, area_id, name, slug, address, phone, description, rating, is_active, created_at, updated_at) VALUES (4, 8, 20, 'Aura Beauty Lounge', 'aura-beauty-lounge', 'Arkan Plaza, Building 4, Sheikh Zayed, Giza', '+20 100 555 9903', 'Exclusive boutique salon specializing in keratin blowouts, signature hair spa rituals, bridal hair art, and customized facial rejuvenation.', 4.95, 1, '2026-08-20 02:36:07', '2026-08-20 02:36:07');
INSERT INTO salons (id, owner_id, area_id, name, slug, address, phone, description, rating, is_active, created_at, updated_at) VALUES (5, 9, 3, 'The Blade & Co. Cutters', 'blade-and-co-cutters', '5th Settlement, Waterway Mall, New Cairo', '+20 100 555 9904', 'Urban contemporary barbershop providing textured crop cuts, beard trims, razor sharp fades, and premium men facial treatments.', 4.6, 1, '2026-08-20 02:36:10', '2026-08-20 02:36:10');
INSERT INTO salons (id, owner_id, area_id, name, slug, address, phone, description, rating, is_active, created_at, updated_at) VALUES (6, 10, 4, 'Silk & Shear Studio', 'silk-and-shear-studio', '45 Baghdad St, Heliopolis, Cairo', '+20 100 555 9905', 'Contemporary minimalist salon known for precision bob cuts, organic hair extensions, anti-frizz glossing, and personalized consultations.', 4.85, 1, '2026-08-20 02:36:11', '2026-08-20 02:36:11');
INSERT INTO salons (id, owner_id, area_id, name, slug, address, phone, description, rating, is_active, created_at, updated_at) VALUES (7, 11, 12, 'Alexandria Grooming Club', 'alexandria-grooming-club', 'Corniche Road, Glim, Alexandria', '+20 100 555 9906', 'Seaside barbershop lounge with sea view haircutting stations, beard oil conditioning, and luxury spa shaves.', 4.75, 1, '2026-08-20 02:36:12', '2026-08-20 02:36:12');
INSERT INTO salons (id, owner_id, area_id, name, slug, address, phone, description, rating, is_active, created_at, updated_at) VALUES (8, 12, 22, 'Elixir Hair & Spa', 'elixir-hair-spa', '30 Gameat El Dowal St, Mohandessin, Giza', '+20 100 555 9907', 'Full service hair lounge and scalp spa offering Olaplex repairing treatments, volume blowouts, and vibrant hair dyeing.', 4.65, 1, '2026-08-20 02:36:13', '2026-08-20 02:36:13');
